import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: random UUID generated by Postgres. */
export const id = () => uuid().primaryKey().default(sql`gen_random_uuid()`);

/**
 * Tenant column. Every tenant-scoped table carries it so Row Level Security
 * can isolate organizations (see migrations/rls.sql).
 */
export const orgId = () => uuid().notNull();

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();
export const updatedAt = () =>
  timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const ts = (name?: string) =>
  name ? timestamp(name, { withTimezone: true }) : timestamp({ withTimezone: true });
